import{_ as i,o as a,c as e,aO as l}from"./chunks/framework.BFrk9dwu.js";const t="/linux/root1.png",n="/linux/root2.png",p="/linux/sudo.png",h="/linux/sudo1.png",o="/linux/%E6%9F%A5%E7%9C%8B%E7%94%A8%E6%88%B7%E7%BB%84.png",d="/linux/%E6%9F%A5%E7%9C%8B%E7%94%A8%E6%88%B7.png",r="/linux/%E6%9F%A5%E7%9C%8B%E7%94%A8%E6%88%B7%E6%89%80%E5%B1%9E%E7%BB%84.png",c="/linux/%E6%9F%A5%E7%9C%8B%E6%9D%83%E9%99%90%E4%BF%A1%E6%81%AF.png",k="/linux/%E6%9D%83%E9%99%90%E6%A1%88%E4%BE%8B.png",C=JSON.parse('{"title":"用户和权限","description":"","frontmatter":{"title":"用户和权限","date":"2026/01/09 13:17:56","permalink":"/linux/zy74cnbv/","sidebarSort":20,"categories":["linux"]},"headers":[],"relativePath":"linux/用户和权限.md","filePath":"linux/用户和权限.md","lastUpdated":1794464674000}'),u={name:"linux/用户和权限.md"};function g(b,s,m,E,F,x){return a(),e("div",null,[...s[0]||(s[0]=[l('<h1 id="用户和权限" tabindex="-1">用户和权限 <a class="header-anchor" href="#用户和权限" aria-label="Permalink to &quot;用户和权限&quot;">​</a></h1><h2 id="root-用户" tabindex="-1">root 用户 <a class="header-anchor" href="#root-用户" aria-label="Permalink to &quot;root 用户&quot;">​</a></h2><p>在 Linux 系统中，root 用户是系统管理员，具有最高权限。</p><p>前期我们一直使用的是普通用户，而普通用户在许多地方的权限是受限的。</p><p>例如：使用普通用户在根目录下创建文件夹时，会提示权限不足。</p><p><img src="'+t+'" alt="创建文件夹权限不足"></p><p>切换到 root 用户后，就可以在根目录下创建文件夹了。</p><p><img src="'+n+'" alt="切换到root用户"></p><p>普通用户的权限，一般在 HOME 目录内是不受限制的。一旦出了 HOME 目录，大多数地方，普通用户仅有只读和执行权限，无修改权限。</p><h3 id="su-命令" tabindex="-1">su 命令 <a class="header-anchor" href="#su-命令" aria-label="Permalink to &quot;su 命令&quot;">​</a></h3><p>su 命令用于切换用户，包括切换到 root 用户。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">su</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-] [username]</span></span></code></pre></div><ul><li><code>-</code> 符号：表示切换到目标用户的环境，包括环境变量和工作目录。</li><li><code>username</code>：目标用户的用户名。如果不指定，默认切换到 root 用户。</li></ul><p>切换用户后，可以通过 <code>exit</code> 命令退出当前用户，也可以使用快捷键 <code>Ctrl+D</code>， 返回之前的用户环境。</p><p>使用普通用户切换到其它用户需要输入密码；而使用 root 用户切换到其它用户不需要输入密码。</p><h3 id="sudo-命令" tabindex="-1">sudo 命令 <a class="header-anchor" href="#sudo-命令" aria-label="Permalink to &quot;sudo 命令&quot;">​</a></h3><p>sudo 命令用于以超级用户权限执行命令。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [command]</span></span></code></pre></div><ul><li><code>command</code>：要以超级用户权限执行的命令。</li></ul><p>但并不是所有的用户都有 sudo 权限。我们需要配置 sudoers 文件，为用户添加 sudo 权限。</p><p><img src="'+p+`" alt="添加sudo权限"></p><p>切换到 root 用户，执行<code>visudo</code>命令，添加如下内容：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 为用户 username 添加 sudo 权限，无需输入密码</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">username</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ALL=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ALL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">NOPASSWD:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ALL</span></span></code></pre></div><ul><li><code>username</code>：要添加 sudo 权限的用户名。</li></ul><p>保存并退出文件后，用户 <code>username</code> 就有了 sudo 权限。</p><p><img src="`+h+'" alt="添加sudo权限成功"></p><p>执行的命令均以 root 运行，且不需要输入密码。</p><h2 id="用户、用户组管理" tabindex="-1">用户、用户组管理 <a class="header-anchor" href="#用户、用户组管理" aria-label="Permalink to &quot;用户、用户组管理&quot;">​</a></h2><p>Linux 中关于权限的管控级别有 2 个：</p><ul><li>用户权限：每个用户都有自己的权限，包括读取、写入、执行等。</li><li>用户组权限：用户组是用户的集合，每个用户组都有自己的权限。</li></ul><h3 id="创建用户组" tabindex="-1">创建用户组 <a class="header-anchor" href="#创建用户组" aria-label="Permalink to &quot;创建用户组&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">groupadd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [groupname]</span></span></code></pre></div><ul><li><code>groupname</code>：要创建的用户组名。</li></ul><p>使用 <code>cat /etc/group</code> 或者 <code>getent group</code> 命令可以查看所有用户组。</p><p><img src="'+o+'" alt="查看所有用户组"></p><p>组名称:组认证(显示为 x):组 ID</p><h3 id="删除用户组" tabindex="-1">删除用户组 <a class="header-anchor" href="#删除用户组" aria-label="Permalink to &quot;删除用户组&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">groupdel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [groupname]</span></span></code></pre></div><ul><li><code>groupname</code>：要删除的用户组名。</li></ul><h3 id="创建用户" tabindex="-1">创建用户 <a class="header-anchor" href="#创建用户" aria-label="Permalink to &quot;创建用户&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">useradd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-g </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] [username]</span></span></code></pre></div><ul><li><code>username</code>：要创建的用户名。</li><li><code>-g</code>：指定用户所属的用户组。不指定时，默认创建一个与用户名相同的用户组。</li><li><code>-d</code>：指定用户的主目录。不指定时，默认创建一个与用户名相同的主目录。</li></ul><p>使用 <code>cat /etc/passwd</code> 或者 <code>getent passwd</code> 命令可以查看所有用户。</p><p><img src="'+d+'" alt="查看所有用户"></p><p>用户名:密码(x):用户 ID:组 ID:描述信息(无用):HOME 目录:执行终端(默认 bash)</p><h3 id="删除用户" tabindex="-1">删除用户 <a class="header-anchor" href="#删除用户" aria-label="Permalink to &quot;删除用户&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">userdel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [-r] [username]</span></span></code></pre></div><ul><li><code>username</code>：要删除的用户名。</li><li><code>-r</code>：删除用户的同时，删除用户的主目录。</li></ul><h3 id="查看用户所属组" tabindex="-1">查看用户所属组 <a class="header-anchor" href="#查看用户所属组" aria-label="Permalink to &quot;查看用户所属组&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [username]</span></span></code></pre></div><ul><li><code>username</code>：要查看的用户名。如果不提供，默认查看当前用户。</li></ul><p><img src="'+r+'" alt="查看用户所属组"></p><h3 id="修改用户所属组" tabindex="-1">修改用户所属组 <a class="header-anchor" href="#修改用户所属组" aria-label="Permalink to &quot;修改用户所属组&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">usermod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -aG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [groupname] [username]</span></span></code></pre></div><ul><li><code>groupname</code>：要修改的用户组名。</li><li><code>username</code>：要修改的用户名。</li></ul><h2 id="查看权限控制" tabindex="-1">查看权限控制 <a class="header-anchor" href="#查看权限控制" aria-label="Permalink to &quot;查看权限控制&quot;">​</a></h2><h3 id="认识权限信息" tabindex="-1">认识权限信息 <a class="header-anchor" href="#认识权限信息" aria-label="Permalink to &quot;认识权限信息&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [file/dir]</span></span></code></pre></div><ul><li><code>file/dir</code>：要查看权限的文件或目录。</li></ul><p><img src="'+c+'" alt="查看权限信息"></p><ul><li>序号 1：表示文件、文件夹的权限控制信息；</li><li>序号 2：表示文件、文件夹所属用户</li><li>序号 3：表示文件、文件夹所属用户组</li></ul><p>权限细节总共分为 10 位，分别表示不同的权限。</p><ul><li>序号 1：表示文件类型，<code>-</code> 表示普通文件，<code>d</code> 表示目录，<code>l</code> 表示软链接。</li><li>序号 2-4：表示文件所有者的权限，<code>r</code> 表示读取权限，<code>w</code> 表示写入权限，<code>x</code> 表示执行权限。</li><li>序号 5-7：表示文件所属用户组的权限，<code>r</code> 表示读取权限，<code>w</code> 表示写入权限，<code>x</code> 表示执行权限。</li><li>序号 8-10：表示其他用户的权限，<code>r</code> 表示读取权限，<code>w</code> 表示写入权限，<code>x</code> 表示执行权限。</li></ul><p><strong>举例：<code>drwxr-xr-x</code>，表示：</strong></p><ul><li>这是一个文件夹，首字母 d 表示；</li><li>所属用户的权限是：读取、写入、执行，rwx；</li><li>所属用户组的权限是：读取、执行，r-x；（-表示无此权限）</li><li>其他用户的权限是：读取、执行，r-x；</li></ul><p><img src="'+k+`" alt="权限案例"></p><p>当前用户 lingping，非文件所属用户和用户组，锁定最后三位权限为：<code>---</code>，表示无权限。</p><h3 id="修改权限控制" tabindex="-1">修改权限控制 <a class="header-anchor" href="#修改权限控制" aria-label="Permalink to &quot;修改权限控制&quot;">​</a></h3><h3 id="chmod-命令" tabindex="-1">chmod 命令 <a class="header-anchor" href="#chmod-命令" aria-label="Permalink to &quot;chmod 命令&quot;">​</a></h3><p>chmod 命令用于修改文件或目录的权限。</p><p>只有文件、文件夹的所属用户或 root 用户才能修改权限。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-R] [mode] [file/dir]</span></span></code></pre></div><ul><li><code>-R</code>：递归修改目录下所有文件的权限。</li><li><code>mode</code>：权限控制模式。</li><li><code>file/dir</code>：要修改权限的文件或目录。</li></ul><p><strong>示例：</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 将文件权限修改为：rwxr-x--x</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># u：用户权限，rwx</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># g：用户组权限，rx</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># o：其他用户权限，x</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> u=rwx,g=rx,o=x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file.txt</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 将目录 test 下所有文件权限修改为：rwxr-x--x</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> u=rwx,g=rx,o=x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>此外还有快捷写法:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 751</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file.txt</span></span></code></pre></div><p><strong>那么这里的数字表示什么？</strong></p><p>权限可以用 3 位数字来表示，第一位表示用户权限，第二位表示用户组权限，第三位表示其他用户权限。</p><p>数字的细节：r 记为 4，w 记为 2，x 记为 1，可以有：</p><ul><li>0：无权限，即---；</li><li>1：执行权限，即--x；</li><li>2：写入权限，即-w-；</li><li>3：写入、执行权限，即-wx；</li><li>4：读取权限，即 r--；</li><li>5：读取、执行权限，即 r-x；</li><li>6：读取、写入权限，即 rw-；</li><li>7：读取、写入、执行权限，即 rwx。</li></ul><p>所以 751 表示：rwx(7)，r-x(5)，--x(1)</p><h3 id="chown-命令" tabindex="-1">chown 命令 <a class="header-anchor" href="#chown-命令" aria-label="Permalink to &quot;chown 命令&quot;">​</a></h3><p>chown 命令用于修改文件或目录的所属用户和用户组。</p><p>普通用户无法修改所属为其它用户或组，所以此命令只适用于 root 用户执行</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chown</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-R] [user[:group]] [file/dir]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 将文件 hello.txt 所属用户修改为 root</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.txt</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 将文件 hello.txt 所属用户组修改为 root</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.txt</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 将文件 hello.txt 所属用户修改为 root，用户组修改为 test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root:test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.txt</span></span></code></pre></div><ul><li><code>-R</code>：递归修改目录下所有文件的所属用户和用户组。</li><li><code>user[:group]</code>：要修改的所属用户和用户组。如果不指定用户组，默认修改为所属用户。</li><li><code>file/dir</code>：要修改所属用户和用户组的文件或目录。</li></ul>`,87)])])}const v=i(u,[["render",g]]);export{C as __pageData,v as default};
